#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

inline long long read() {
    long long x = 0;
    int ch = getchar();
    while (ch != EOF && (ch < '0' || ch > '9'))
        ch = getchar();
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x;
}

int main() {
    int n = static_cast<int>(read());
    int k = static_cast<int>(read());

    vector<int> pre(n + 1, n), cur(n + 1), q(n + 1);
    pre[0] = 0;

    for (int j = 0; j < k; ++j) {
        long long lt = read();
        long long rt = read();
        cur = pre;

        int start = static_cast<int>(min<long long>(n, rt));
        int l = 0, r = -1, added = -1;

        for (int i = start; i >= 0; --i) {
            int upper = static_cast<int>(min<long long>(n, rt - i));

            while (added < upper) {
                int x = ++added;
                while (l <= r && pre[x] <= pre[q[r]])
                    --r;
                q[++r] = x;
            }

            long long lower = lt - i;
            while (l <= r && q[l] < lower)
                ++l;

            if (l <= r)
                cur[i] = min(cur[i], pre[q[l]] + 1);
        }

        l = 0;
        r = -1;
        long long width = rt - lt;

        for (int i = 0; i <= n && i <= rt; ++i) {
            long long lower = static_cast<long long>(i) - width;
            while (l <= r && q[l] < lower)
                ++l;
            while (l <= r && pre[i] <= pre[q[r]])
                --r;
            q[++r] = i;
            cur[i] = min(cur[i], pre[q[l]] + 2);
        }

        pre.swap(cur);
    }

    if (pre[n] < n)
        printf("Full\n%d\n", pre[n]);
    else
        puts("Hungry");

    return 0;
}

